code.source:
#include <stdio.h>

int main(void) {
    int fish = 10;
    int *p = &fish;

    printf("Before: fish = %d\n", fish);

    int copy = *p;
    printf("Read through p: %d\n", copy);

    *p = 25;
    printf("After *p = 25: fish = %d\n", fish);

    *p = *p + 5;
    printf("After *p = *p + 5: fish = %d\n", fish);

    (*p)++;
    printf("After (*p)++: fish = %d\n", fish);
    return 0;
}

